package com.cbs.contracts;
import static org.assertj.core.api.Assertions.*;
import static com.cbs.contracts.ContractModels.*;
import com.cbs.accounts.AccountModels;
import com.cbs.products.ProductModels;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class LoanArrearsTest {
 private final LocalDate start=LocalDate.of(2026,1,31);
 private Definition definition(String currency){var product=new ProductModels.Product(UUID.randomUUID(),"TEST","Test","",ProductModels.Type.CURRENT,currency,"0","0",UUID.randomUUID(),"100",true,1,Instant.EPOCH,Instant.EPOCH);var a=new AccountModels.Definition(UUID.randomUUID(),UUID.randomUUID(),"1",1,UUID.randomUUID(),"C1",UUID.randomUUID(),"Test","Test",AccountModels.State.ACTIVE,product,Instant.EPOCH);var o=new Open(0,Type.LOAN,a.id(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,"200","36.5","0",365,start,start.plusMonths(2),2,"TEST","Test");return new Definition(UUID.randomUUID(),a.bankId(),a,o);}
 private Posting opening(Definition d){return new Posting(d.id(),d,Kind.OPEN,start,new Position("0","0","0",start,false),new Position("200","0","0",start,false),"200","0",null,"Open");}
 private Posting accrue(Posting previous,LocalDate date){var p=previous.after();var c=interest(p.principal(),previous.contract().terms().annualRatePercent(),365,p.accruedThrough(),date,p.carry(),scale(previous.contract()));return new Posting(UUID.randomUUID(),previous.contract(),Kind.ACCRUE,date,p,new Position(p.principal(),text(decimal(p.interest()).add(decimal(c.interest()))),c.carry(),date,false),"0","0",null,"Accrue");}
 @Test void postedInterestUsesCalendarDueDatesAndBucketsNotProjectedInterest(){var open=opening(definition("KES"));var date=LocalDate.of(2026,3,15);var a=accrue(open,date);var r=LoanArrears.calculate(List.of(open,a),date);assertThat(r.reconciled()).isTrue();assertThat(r.accrualComplete()).isTrue();assertThat(r.overdue()).isEqualTo(new LoanArrears.Totals("100","5.6","0","105.6"));assertThat(r.outstanding().interest()).isEqualTo("8.6");assertThat(r.daysPastDue()).isEqualTo(15);assertThat(r.buckets().get("CURRENT").interest()).isEqualTo("3");assertThat(LoanArrears.calculate(List.of(open),date).accrualComplete()).isFalse();assertThat(LoanArrears.calculate(List.of(open),date).outstanding().interest()).isEqualTo("0");}
 @Test void zeroMinorCurrenciesAndCarryAcrossDailyAccrualsReconcile(){var events=new ArrayList<Posting>();events.add(opening(definition("UGX")));for(int day=1;day<=65;day++)events.add(accrue(events.getLast(),start.plusDays(day)));var r=LoanArrears.calculate(events,start.plusDays(65));assertThat(r.reconciled()).isTrue();assertThat(r.outstanding().interest()).isEqualTo("13");assertThat(r.instalments()).allSatisfy(x->assertThat(x.interest()).doesNotContain("."));}
 @Test void repaymentReversalRestoresDueAmountsAndReopensCashPromise(){var open=opening(definition("KES"));var p=new Posting(UUID.randomUUID(),open.contract(),Kind.REPAY,start,open.after(),new Position("150","0","0",start,false),"-50","0",null,"Pay");var promise=new LoanCollectionsService.Promise(UUID.randomUUID(),"50",start,List.of());assertThat(LoanCollectionsService.promiseStatus(promise,List.of(open,p),start).status()).isEqualTo("FULFILLED");var reverse=new Posting(UUID.randomUUID(),open.contract(),Kind.REVERSE,start,p.after(),open.after(),"50","0",null,"Reverse",p.id());var events=List.of(open,p,reverse);assertThat(LoanArrears.calculate(events,start.plusMonths(1).plusDays(1)).overdue().principal()).isEqualTo("100");assertThat(LoanCollectionsService.promiseStatus(promise,events,start.plusDays(1)).status()).isEqualTo("BROKEN");assertThat(LoanArrears.calculate(List.of(open,p),start.plusMonths(1).plusDays(1)).overdue().principal()).isEqualTo("50");}
 @Test void promiseExcludesPriorCashAndDistinguishesLateFulfilment(){var open=opening(definition("KES"));var paid=new Posting(UUID.randomUUID(),open.contract(),Kind.REPAY,start.plusDays(2),open.after(),new Position("180","0","0",start.plusDays(2),false),"-20","0",null,"Pay");var promise=new LoanCollectionsService.Promise(UUID.randomUUID(),"20",start.plusDays(1),List.of());assertThat(LoanCollectionsService.promiseStatus(promise,List.of(open,paid),start.plusDays(2)).status()).isEqualTo("FULFILLED_LATE");promise=new LoanCollectionsService.Promise(UUID.randomUUID(),"20",start.plusDays(3),List.of(paid.id()));assertThat(LoanCollectionsService.promiseStatus(promise,List.of(open,paid),start.plusDays(2)).paid()).isEqualTo("0");}
 @Test void exactAgeingBoundaries(){assertThat(List.of(0L,1L,30L,31L,60L,61L,90L,91L,180L,181L).stream().map(LoanArrears::bucket)).containsExactly("CURRENT","1_30","1_30","31_60","31_60","61_90","61_90","91_180","91_180","181_PLUS");}
 @Test void feesAgeSeparatelyAndWaiverDoesNotFulfilPromise(){var open=opening(definition("KES"));var id=UUID.randomUUID();var receivable=UUID.randomUUID();var income=UUID.randomUUID();var date=start.plusDays(1);var change=new LoanFeeModels.Change(0,open.contract().id(),LoanFeeModels.Operation.FEE_ASSESS,null,start,start,receivable,income,"10","FEE","Agreed fee");var assess=new Posting(id,open.contract(),Kind.FEE_ASSESS,start,open.after(),open.after(),"0","0",null,"Fee",null,null,null,new LoanFeeModels.Details(change,id,start,receivable,income,"0","10"));var waiver=new Posting(UUID.randomUUID(),open.contract(),Kind.FEE_WAIVE,date,open.after(),open.after(),"0","0",null,"Waive",null,null,null,new LoanFeeModels.Details(change,id,start,receivable,income,"10","4"));var events=List.of(open,assess,waiver);assertThat(LoanArrears.calculate(events,date).overdue().fees()).isEqualTo("4");assertThat(LoanArrears.calculate(events,date).overdue().principal()).isEqualTo("0");assertThat(LoanCollectionsService.promiseStatus(new LoanCollectionsService.Promise(UUID.randomUUID(),"6",start,List.of()),events,date).status()).isEqualTo("BROKEN");}
 @Test void correctedOpeningHasNoOutstandingInstalments(){var open=opening(definition("RWF"));var reverse=new Posting(UUID.randomUUID(),open.contract(),Kind.REVERSE,start,open.after(),new Position("0","0","0",start,true),"-200","0",null,"Reverse",open.id());var r=LoanArrears.calculate(List.of(open,reverse),start.plusYears(1));assertThat(r.reconciled()).isTrue();assertThat(r.outstanding().total()).isEqualTo("0");}
}
